package dev.smpcristalix.pvpcombat.listener;import dev.smpcristalix.pvpcombat.PvPCombatPlugin;import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.service.CombatService;import org.bukkit.Material;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.EntityPickupItemEvent;import org.bukkit.event.inventory.*;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;/** Totem cap and combat replenishment restrictions. */public final class TotemListener implements Listener{private final CombatService combat;private PvPCombatSettings settings;public TotemListener(CombatService c,PvPCombatSettings s){combat=c;settings=s;}public void reload(PvPCombatSettings s){settings=s;}@EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void onPickup(EntityPickupItemEvent e){if(!(e.getEntity() instanceof Player p))return;ItemStack stack=e.getItem().getItemStack();if(stack.getType()!=Material.TOTEM_OF_UNDYING)return;if(count(p)+stack.getAmount()>settings.maxTotemsCarried()){e.setCancelled(true);p.sendMessage("§cЛимит тотемов: "+settings.maxTotemsCarried());return;}if(!combat.inCombat(p)||settings.allowExternalTotemSourcesInCombat())return;String owner=stack.hasItemMeta()?stack.getItemMeta().getPersistentDataContainer().get(PvPCombatPlugin.TROPHY_TOTEM_KEY,PersistentDataType.STRING):null;if(!p.getUniqueId().toString().equals(owner)){e.setCancelled(true);p.sendMessage("§cВо время Combat нельзя пополнять тотемы из внешних источников.");return;}var meta=stack.getItemMeta();meta.getPersistentDataContainer().remove(PvPCombatPlugin.TROPHY_TOTEM_KEY);stack.setItemMeta(meta);}@EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void onClick(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;ItemStack i=e.getCurrentItem();if(i==null||i.getType()!=Material.TOTEM_OF_UNDYING)return;boolean ext=e.getClickedInventory()!=null&&e.getClickedInventory()!=p.getInventory();if(combat.inCombat(p)&&ext&&!settings.allowExternalTotemSourcesInCombat()){e.setCancelled(true);p.sendMessage("§cВо время Combat нельзя брать тотемы из контейнеров.");return;}if(count(p)>=settings.maxTotemsCarried()&&ext)e.setCancelled(true);}@EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void onDrag(InventoryDragEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(combat.inCombat(p)&&!settings.allowExternalTotemSourcesInCombat()&&e.getOldCursor().getType()==Material.TOTEM_OF_UNDYING)e.setCancelled(true);}public int count(Player p){int n=0;for(ItemStack i:p.getInventory().getContents())if(i!=null&&i.getType()==Material.TOTEM_OF_UNDYING)n+=i.getAmount();return n;}}
